import Domain
import Foundation
import Testing
@testable import Data

/// The fake's answers per kind (generated by `bun contract` from api/src/claude-fake.ts) read by the app's own
/// decoders:
/// an answer shape the app cannot read fails here, not on a tutor's phone (D80).
private let samples: [(kind: String, json: Data)] = {
    guard let directory = Bundle.module.url(forResource: "Contract", withExtension: nil),
          let names = try? FileManager.default.contentsOfDirectory(atPath: directory.path) else { return [] }
    return names.filter { $0.hasSuffix(".json") }.sorted().compactMap { name in
        guard let data = try? Data(contentsOf: directory.appending(path: name)) else { return nil }
        return (String(name.dropLast(5)), data)
    }
}()

/// `{ id, result }` around a sample, as the API sends it.
private func envelope(_ result: Data) -> Data {
    Data(#"{"id":"11111111-1111-1111-1111-111111111111","result":"#.utf8) + result + Data("}".utf8)
}

/// One decoder per kind the API answers, as the app's calls read them.
private let decoders: [String: @Sendable (Data) -> Bool] = {
    func decodes<T: Decodable>(_: T.Type) -> @Sendable (Data) -> Bool {
        { (try? JSONDecoder().decode(T.self, from: envelope($0))) != nil }
    }
    var table: [String: @Sendable (Data) -> Bool] = [
        "scan_register": decodes(ScanEnvelope.self),
        "check_paper": decodes(CheckEnvelope.self),
        "parse_textbook": decodes(TextbookEnvelope.self),
        "check": decodes(ChecksEnvelope.self),
        "placement": decodes(PlacementEnvelope.self),
        "sheet": decodes(MadeEnvelope<SheetResult>.self),
        "worked_example": decodes(MadeEnvelope<WorkedExample>.self),
        "figure": decodes(MadeEnvelope<FigureContent>.self),
        "brief": decodes(MadeEnvelope<Brief>.self),
        "parse_school": decodes(MadeEnvelope<ParseSchoolResult>.self),
        "mock": decodes(MadeEnvelope<MockResult>.self),
        "gap_report": decodes(MadeEnvelope<GapResult>.self),
        "read_marks": decodes(MadeEnvelope<ReadMarksResult>.self),
    ]
    for kind in ["note", "can_do", "not_on_track", "test_tomorrow"] {
        table[kind] = decodes(MadeEnvelope<MessageResult>.self)
    }
    // V1's four are read from the result's text, as History reads a row.
    for kind in GenerationKind.allCases {
        table[kind.rawValue] = { data in
            String(bytes: data, encoding: .utf8).flatMap { GenerationResult.decode(kind: kind, output: $0) } != nil
        }
    }
    return table
}()

@Test func theContractHoldsASampleForEveryKind() {
    #expect(samples.count == 22)
}

/// The API's answers the app no longer asks for: /ai/plan names a group's first topic for build 27's plans; since
/// Phase 18 the server's plan job does that itself.
private let notAsked: Set<String> = ["plan"]

@Test(arguments: samples.map(\.kind).filter { !notAsked.contains($0) })
func everySampleAnswerReadsWithTheAppsDecoder(kind: String) throws {
    let sample = try #require(samples.first { $0.kind == kind })
    let decode = try #require(decoders[kind], "no decoder for the API's \(kind) answer")
    #expect(decode(sample.json), "the app cannot read the API's \(kind) answer")
}
